<?php
namespace App\Http\Controllers; use App\Models\{FoodCategory,FoodDonation,DonationStatusHistory,DonationPhoto}; use Illuminate\Http\Request;
class DonationController extends Controller { public function index(){ $donations=FoodDonation::with('category')->where('donor_id',auth()->user()->partnerProfile->profile_id)->get(); return view('donations.index',compact('donations'));} public function available(Request $r){$donations=FoodDonation::with('category','donor.user')->where('donation_status','AVAILABLE')->where('expiry_datetime','>',now())->when($r->category_id,fn($q)=>$q->where('category_id',$r->category_id))->get(); return view('donations.available',['donations'=>$donations,'categories'=>FoodCategory::all()]);} public function create(){return view('donations.form',['donation'=>new FoodDonation(),'categories'=>FoodCategory::all()]);} public function store(Request $r){$data=$this->data($r); $data['donor_id']=auth()->user()->partnerProfile->profile_id; $data['current_quantity']=$data['donation_quantity']; $d=FoodDonation::create($data); DonationStatusHistory::create(['donation_id'=>$d->donation_id,'new_status'=>'AVAILABLE','changed_by'=>auth()->id(),'remarks'=>'Donation created']); if($r->hasFile('photo')) DonationPhoto::create(['donation_id'=>$d->donation_id,'file_path'=>$r->file('photo')->store('donation_photos','public')]); return redirect('/donations');} public function edit(FoodDonation $donation){return view('donations.form',['donation'=>$donation,'categories'=>FoodCategory::all()]);} public function update(Request $r, FoodDonation $donation){$donation->update($this->data($r)); return redirect('/donations');} public function cancel(FoodDonation $donation){$old=$donation->donation_status; $donation->update(['donation_status'=>'CANCELLED']); DonationStatusHistory::create(['donation_id'=>$donation->donation_id,'old_status'=>$old,'new_status'=>'CANCELLED','changed_by'=>auth()->id(),'remarks'=>'Cancelled by donor']); return back();} private function data(Request $r){return $r->validate(['category_id'=>'required|exists:food_categories,category_id','food_name'=>'required','description'=>'nullable','donation_quantity'=>'required|numeric','measurement_unit'=>'required','expiry_datetime'=>'required|date','pickup_address'=>'required','storage_type'=>'nullable','halal_status'=>'nullable','photo'=>'nullable|image']);} }
